const listCoresearchCells = `-- name: ListCoresearchCells :many
SELECT id, workspace_id, chat_id, seq, author_user_id, agent_run_id, kernel, source, status, execution_count, outputs, outputs_blob, created_at, started_at, finished_at, failure_reason, claimed_daemon_id FROM coresearch_cell WHERE workspace_id= $1 AND chat_id= $2 ORDER BY seq
`

type ListCoresearchCellsParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ChatID      uuid.UUID `json:"chat_id"`
}

func (q *Queries) ListCoresearchCells(ctx context.Context, arg ListCoresearchCellsParams) ([]CoresearchCell, error) {
	rows, err := q.db.Query(ctx, listCoresearchCells, arg.WorkspaceID, arg.ChatID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CoresearchCell
	for rows.Next() {
		var i CoresearchCell
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ChatID,
			&i.Seq,
			&i.AuthorUserID,
			&i.AgentRunID,
			&i.Kernel,
			&i.Source,
			&i.Status,
			&i.ExecutionCount,
			&i.Outputs,
			&i.OutputsBlob,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.FailureReason,
			&i.ClaimedDaemonID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

